using Microsoft.Extensions.Logging;

namespace X3Code.Azure.Utils.Storage;

/// <summary>
/// The log events the blob storage writes. Generated by the LoggerMessage source generator, so a
/// call costs nothing while the level is switched off.
/// </summary>
/// <remarks>
/// Everything goes through <see cref="ILogger"/>, the abstraction. This library brings no sink and
/// no configuration; where the events end up is entirely the consuming application's decision.
/// </remarks>
internal static partial class StorageLog
{
    [LoggerMessage(EventId = 4000, Level = LogLevel.Debug,
        Message = "Downloaded blob [{Path}] from container [{Container}], {ByteCount} bytes.")]
    internal static partial void Downloaded(ILogger logger, string path, string container, long byteCount);

    [LoggerMessage(EventId = 4001, Level = LogLevel.Debug,
        Message = "Uploaded blob [{Path}] to container [{Container}].")]
    internal static partial void Uploaded(ILogger logger, string path, string container);

    [LoggerMessage(EventId = 4002, Level = LogLevel.Debug,
        Message = "Deleted blob [{Path}] from container [{Container}].")]
    internal static partial void Deleted(ILogger logger, string path, string container);

    [LoggerMessage(EventId = 4003, Level = LogLevel.Warning,
        Message = "Blob [{Path}] was not found in container [{Container}].")]
    internal static partial void NotFound(ILogger logger, string path, string container);
}
